'use strict';
/* ===== text8.js: city 6 (Islands of Hidden Knowledge) strings, EN / AR ===== */
S('room.dock', `Islands of Hidden Knowledge: The Misty Dock`, `Islands of Hidden Knowledge: The Misty Dock`);
S('room.isle1', `Island of Probabilities`, `Island of Probabilities`);
S('room.isle2', `Island of Hidden Groups`, `Island of Hidden Groups`);
S('room.isle3', `Twin Paths of Learning`, `Twin Paths of Learning`);
S('room.gate6', `The Convergence Gate`, `The Convergence Gate`);
S('room.core', `The Learning Core`, `The Learning Core`);
S('spk.keeper', `Probability Keeper`, `Probability Keeper`); S('spk.seeker', `Pattern Seeker`, `Pattern Seeker`); S('spk.sagee', `Sage of Examples`, `Sage of Examples`); S('spk.sagep', `Sage of Patterns`, `Sage of Patterns`);
S('spk.nullc', `Null`, `Null`); S('spk.ferry1', `Ferryman Ahab`, `Ferryman Ahab`); S('spk.ferry2', `Ferryman Bo`, `Ferryman Bo`); S('spk.lag', `Lag`, `Lag`); S('spk.core', `The Learning Core`, `The Learning Core`);
S('obj6.travel', `Take the ferry from the river mouth, or open the map (M).`, `استقلّ العبّارة من مصب النهر، أو افتح الخريطة (M).`);
S('obj6.keeper', `Walk north to the Island of Probabilities and speak with the Probability Keeper.`, `امشِ شمالًا إلى Island of Probabilities وتحدّث مع Probability Keeper.`);
S('obj6.seeker', `Cross the east boardwalk to the Island of Hidden Groups.`, `اعبر الممر الخشبي الشرقي إلى Island of Hidden Groups.`);
S('obj6.seeker2', `Speak with the Pattern Seeker.`, `تحدّث مع Pattern Seeker.`);
S('obj6.sages', `Take the south boardwalk to the Twin Paths of Learning.`, `اتبع الممر الخشبي الجنوبي إلى Twin Paths of Learning.`);
S('obj6.sages2', `Speak with the two Sages.`, `تحدّث مع الحكيمين.`);
S('obj6.gate', `Follow the northeast boardwalk to the Convergence Gate.`, `اتبع الممر الشمالي الشرقي إلى Convergence Gate.`);
S('obj6.keeper2', `Speak with the Probability Keeper at the gate.`, `تحدّث مع Probability Keeper عند البوابة.`);
S('obj6.core', `Go through the opened gate to the Learning Core.`, `اعبر البوابة المفتوحة إلى Learning Core.`);
S('obj6.boss', `Face Lag at the Learning Core.`, `واجه Lag عند Learning Core.`);
S('obj6.end', `Walk south, out of the Core chamber.`, `امشِ جنوبًا للخروج من غرفة Core.`);
S('lock.isle2', `The east boardwalk is hidden in mist. The Probability Keeper must show you how to read it first.`, `الممر الشرقي مخفي في الضباب. على Probability Keeper أن يريكما كيف تقرآنه أولًا.`);
S('lock.isle3', `The south boardwalk is hidden in mist. Find the hidden groups first.`, `الممر الجنوبي مخفي في الضباب. اعثرا على المجموعات المخفية أولًا.`);
S('lock.gate6', `The northeast boardwalk is hidden in mist. The Twin Paths hold the next lesson.`, `الممر الشمالي الشرقي مخفي في الضباب. الدرس التالي عند Twin Paths.`);
S('lock.core', `The Convergence Gate is sealed. Finish the Six Gates trial first.`, `Convergence Gate مغلقة. أنهيا تجربة Six Gates أولًا.`);
S('tile.isign1', `A signpost: "North: Probabilities. East: Hidden Groups. South: Twin Paths. Northeast: the Gate."`, `لافتة: "شمالًا: Probabilities. شرقًا: Hidden Groups. جنوبًا: Twin Paths. شمالًا شرقيًا: Gate."`);
S('tile.isign2', `Another sign, half in mist: "Not every answer is certain. Report how sure you are."`, `لافتة أخرى نصفها في الضباب: "ليست كل إجابة مؤكدة. أخبر بمدى ثقتك."`);

/* arrival */
S('c6.a1', `Islands drift in a silver mist. Lanterns glow along a wooden dock, and the five fragments in your pack hum softly.`, `جزر تطفو في ضباب فضي. فوانيس تتوهج على رصيف خشبي، والشظايا الخمس في حقيبتك تُصدر طنينًا خافتًا.`);
S('c6.a2', `The fragments are lining up. Whatever the Core did, it ended here.`, `الشظايا تصطف. مهما كان ما فعله الـ Core فقد انتهى هنا.`);
S('c6.a3', `A stranger on the north island waves a lantern. Let us go and ask what this place is.`, `غريب في الجزيرة الشمالية يلوّح بفانوس. لنذهب ونسأل ما هذا المكان.`);
S('c6.keeper.wait', `Come to my island when you are ready. The mist will not hurry you.`, `تعالوا إلى جزيرتي حين تكونون مستعدين. لن يستعجلكم الضباب.`);
S('c6.keeper.idle', `Every prediction is a number between 0 and 1. Choose your threshold with care.`, `كل Prediction هو رقم بين 0 و 1. اختر الـ Threshold بعناية.`);
S('c6.seeker.idle', `The data has a shape. Look long enough and it shows you.`, `للبيانات شكل. انظر طويلًا فتريك إياه.`);
S('c6.null.idle', `I belong. I simply belong to no group yet. That is allowed.`, `أنا أنتمي. فقط لا أنتمي إلى مجموعة بعد. وهذا مسموح.`);
S('c6.sagee.idle', `Give me examples with answers and I will learn to answer.`, `أعطني أمثلة معها إجابات وسأتعلم أن أجيب.`);
S('c6.sagep.idle', `Give me examples with no answers and I will learn to see the shape.`, `أعطني أمثلة بلا إجابات وسأتعلم أن أرى الشكل.`);
S('c6.ferry.idle', `Two boats, two kinds of cargo, two ways to learn.`, `قاربان ونوعان من البضائع وطريقتان للتعلم.`);

/* scene 1 */
S('c6.s1.1', `This island does not deal in certainty, traveler. Welcome.`, `هذه الجزيرة لا تتعامل بالتأكد المطلق أيها المسافر. أهلًا بكما.`);
S('c6.s1.2', `A creature may be dangerous. Or it may be safe. Rarely can I say yes or no for certain.`, `قد يكون المخلوق خطرًا. وقد يكون آمنًا. نادرًا ما أستطيع قول نعم أو لا بيقين.`);
S('c6.s1.3', `So the model gives a probability, a number between 0 and 1, instead of a flat answer?`, `إذن يعطي الـ Model احتمالًا، رقمًا بين 0 و 1، بدل إجابة جامدة؟`);
S('c6.s1.4', `Yes. **Logistic regression** is a classification method. It first computes a score **z**, then a function called the **sigmoid** turns z into a probability between 0 and 1.`, `نعم. **Logistic regression** طريقة Classification. تحسب أولًا درجة **z** ثم تحوّلها دالة اسمها **sigmoid** إلى احتمال بين 0 و 1.`);
S('c6.s1.5', `Then a **threshold** decides: at or above it, the creature is labeled dangerous. Below it, safe. Let me show you.`, `ثم يقرر الـ **Threshold**: عند الحد أو فوقه يُوسم المخلوق خطرًا، وتحته آمنًا. دعني أريكما.`);
S('c6.s1.win', `So the model does not simply answer. It says how likely, and then we choose where to draw the line.`, `إذن الـ Model لا يجيب فقط. يقول مدى الاحتمال، ثم نختار أين نرسم الخط.`);
S('c6.s1.win2', `And every choice of threshold trades one mistake for another: false alarms against missed dangers.`, `وكل اختيار للـ Threshold يبدّل خطأً بخطأ: إنذارات كاذبة مقابل أخطار فاتتنا.`);
S('c6.s1.win3', `Take this: the Probability Compass. It points to the creatures the model is least sure about.`, `خذا هذه: Probability Compass. تشير إلى المخلوقات التي الـ Model أقل تأكدًا منها.`);
S('c6.s1.t1', `The east boardwalk is clear now. The Pattern Seeker lives on the Island of Hidden Groups.`, `الممر الشرقي صار واضحًا. يعيش Pattern Seeker في Island of Hidden Groups.`);
S('c6.t1.title', `The Island of Probabilities`, `The Island of Probabilities`);
S('c6.sig.z', `Score z`, `الدرجة z`); S('c6.sig.p', `Probability σ(z)`, `الاحتمال σ(z)`);
Q('c6.t11', [`σ(z) = 1 / (1 + e^−z) turns a score into a probability. For z = 2 the table says σ(z) = 0.881. What does this mean?`, `σ(z) = 1 / (1 + e^−z) يحوّل الدرجة إلى احتمال. عند z = 2 يقول الجدول إن σ(z) = 0.881. ماذا يعني ذلك؟`],
  [`The model estimates about an 88% chance that the creature is dangerous`, `يقدّر الـ Model أن احتمال كون المخلوق خطرًا نحو 88%`], [`88% of all creatures are dangerous`, `88% من كل المخلوقات خطرة`], [`The model is 88% accurate`, `الـ Model دقته 88%`],
  [`The sigmoid output is read as a probability for one creature.`, `يُقرأ ناتج الـ Sigmoid كاحتمال لمخلوق واحد.`], [`It is not about all creatures, and not about accuracy.`, `لا يتعلق بكل المخلوقات، ولا بالدقة.`],
  [`σ(z) is the model's estimated probability for this one creature. A high score z gives a probability near 1.`, `σ(z) هو احتمال الـ Model المقدّر لهذا المخلوق وحده. الدرجة z العالية تعطي احتمالًا قريبًا من 1.`]);
Q('c6.t12', [`Emberfox gets a probability of 0.63. The threshold is 0.70. What label does the model give?`, `يحصل Emberfox على احتمال 0.63. الـ Threshold هو 0.70. ما الـ Label الذي يعطيه الـ Model؟`],
  [`Safe, because 0.63 is below 0.70`, `آمن، لأن 0.63 أقل من 0.70`], [`Dangerous, because 0.63 is above 0.5`, `خطر، لأن 0.63 أعلى من 0.5`], [`It cannot tell`, `لا يستطيع أن يحدد`],
  [`Compare the probability to the threshold, not to 0.5.`, `قارن الاحتمال بالـ Threshold لا بـ 0.5.`], [`Dangerous means at or above the threshold.`, `خطر تعني عند الـ Threshold أو فوقه.`],
  [`The threshold here is 0.70. Since 0.63 < 0.70, the label is safe.`, `الـ Threshold هنا 0.70. وبما أن 0.63 < 0.70 فالـ Label هو آمن.`]);
Q('c6.t13', [`We lower the threshold from 0.5 to 0.3. What happens to the number of creatures labeled dangerous?`, `نخفّض الـ Threshold من 0.5 إلى 0.3. ماذا يحدث لعدد المخلوقات الموسومة خطرة؟`],
  [`It stays the same or grows: more creatures now count as positive`, `يبقى كما هو أو يزداد: صار عدد أكبر من المخلوقات يُحسب Positive`], [`It shrinks`, `يقل`], [`It always doubles`, `يتضاعف دائمًا`],
  [`More creatures have a probability of at least 0.3 than at least 0.5.`, `عدد المخلوقات التي احتمالها 0.3 فأكثر أكبر من التي احتمالها 0.5 فأكثر.`], [`Lower bar, more creatures pass it.`, `حد أدنى أخفض، فيعبره عدد أكبر.`],
  [`A lower threshold labels more creatures positive. You catch more dangers but raise more false alarms.`, `الـ Threshold الأقل يوسم مزيدًا من المخلوقات Positive. تلتقط أخطارًا أكثر لكن الإنذارات الكاذبة تزداد.`]);
S('c6.thr.v', `Threshold: {v}`, `Threshold: {v}`); S('c6.thr.tp', `Dangerous creatures caught: {v}`, `المخلوقات الخطرة التي التُقطت: {v}`); S('c6.thr.fp', `False alarms: {v}`, `إنذارات كاذبة: {v}`); S('c6.thr.fn', `Dangers missed: {v}`, `أخطار فاتتنا: {v}`);
S('c6.thr.d', `dangerous`, `خطر`); S('c6.thr.s', `safe`, `آمن`); S('c6.thr.flag', `flagged`, `موسوم`);
H('c6.t14', [`Slide the threshold so that no dangerous creature is missed, with as few false alarms as possible. (A creature is flagged when its probability is at or above the threshold.)`, `حرّك الـ Threshold بحيث لا يفوتنا أي مخلوق خطر، مع أقل عدد ممكن من الإنذارات الكاذبة. (يُوسم المخلوق عندما يكون احتماله عند الـ Threshold أو فوقه.)`],
  [`The lowest dangerous probability is 0.45. Your threshold must not be higher than that.`, `أقل احتمال لمخلوق خطر هو 0.45. يجب ألا يكون الـ Threshold أعلى منه.`], [`Lower the threshold only until no danger is missed. Going lower adds false alarms.`, `اخفض الـ Threshold فقط حتى لا يفوتك خطر. الخفض أكثر يضيف إنذارات كاذبة.`],
  [`At 0.40 or 0.45, all four dangerous creatures are caught and only Ripple is a false alarm. Lower values also flag Mistling.`, `عند 0.40 أو 0.45 تُلتقط المخلوقات الخطرة الأربعة ولا يكون إنذار كاذب إلا Ripple. القيم الأقل تَسِم Mistling أيضًا.`]);
Q('c6.t15', [`The model flagged a creature as dangerous, but it was actually safe. Which cell of the confusion matrix is that?`, `وسم الـ Model مخلوقًا خطرًا لكنه كان آمنًا في الواقع. أي خلية في الـ Confusion matrix هذه؟`],
  [`False Positive`, `False Positive`], [`False Negative`, `False Negative`], [`True Positive`, `True Positive`],
  [`The model said positive (dangerous), but the truth was negative.`, `قال الـ Model Positive (خطر)، لكن الحقيقة كانت Negative.`], [`The first word tells whether the model was right; the second is what the model said.`, `الكلمة الأولى تقول إن كان الـ Model محقًا؛ والثانية ما قاله.`],
  [`A false positive is a false alarm: the model said positive, the truth was negative.`, `الـ False Positive إنذار كاذب: قال الـ Model Positive والحقيقة Negative.`]);
Q('c6.t16', [`Four creatures are truly dangerous. The model catches 3 of them and misses 1. What is the recall?`, `أربعة مخلوقات خطرة فعلًا. يلتقط الـ Model 3 منها ويفوّت 1. كم الـ Recall؟`],
  [`3 / 4 = 75%`, `3 / 4 = 75%`], [`3 / 7`, `3 / 7`], [`4 / 3`, `4 / 3`],
  [`Recall = True Positives / (True Positives + False Negatives).`, `Recall = True Positives / (True Positives + False Negatives).`], [`Of all truly dangerous creatures, how many were found?`, `من كل المخلوقات الخطرة فعلًا، كم وُجد؟`],
  [`Recall asks: of the truly positive cases, how many did we catch? 3 caught out of 4 = 75%.`, `يسأل الـ Recall: من الحالات Positive فعلًا، كم التقطنا؟ 3 من 4 = 75%.`]);

/* scene 2 */
S('c6.s2.1', `Nothing here has a name tag. These creatures have never been labeled, and no one will tell me what they are.`, `لا اسم على أي من هذه المخلوقات. لم تُوسم قط، ولن يخبرني أحد ما هي.`);
S('c6.s2.2', `No labels at all? Then we cannot learn by checking answers.`, `بلا Labels إطلاقًا؟ إذن لا نستطيع أن نتعلم بفحص الإجابات.`);
S('c6.s2.3', `We can still look for structure. Creatures that are alike should sit close together. That is **clustering**, a kind of **unsupervised learning**.`, `لكننا نستطيع البحث عن بنية. المخلوقات المتشابهة يجب أن تكون قريبة. هذا هو **Clustering**، نوع من **Unsupervised learning**.`);
S('c6.s2.4', `How do we decide how many groups there are?`, `كيف نقرر كم عدد المجموعات؟`);
S('c6.s2.5', `With **K-Means** you choose K, the number of clusters you ask for. Elbow and Silhouette checks can help you choose it. Try different values.`, `في **K-Means** تختار K، عدد الـ Clusters الذي تطلبه. يساعدك فحص Elbow وSilhouette على اختياره. جرّب قيمًا مختلفة.`);
S('c6.s2.win', `Three groups. Small and dim, large winged, and bright glowing creatures. I think I can see them.`, `ثلاث مجموعات. صغيرة خافتة، وكبيرة الأجنحة، ومتوهجة. أظنني أراها.`);
S('c6.s2.win2', `But remember: finding three clusters does not prove that there are three real species. The algorithm shows patterns. You and the scientists must check what they mean.`, `لكن تذكرا: العثور على ثلاثة Clusters لا يثبت وجود ثلاثة أنواع حقيقية. الخوارزمية تُظهر أنماطًا. وعليكما والعلماء فحص معناها.`);
S('c6.s2.win3', `Take this: the Cluster Lens. It outlines the groups the data seems to hold.`, `خذا هذه: Cluster Lens. تُظهر حدود المجموعات التي يبدو أن البيانات تحويها.`);
S('c6.s2.t1', `The south boardwalk has appeared in the mist. The Twin Paths of Learning lie that way.`, `ظهر الممر الجنوبي في الضباب. و Twin Paths of Learning في ذلك الاتجاه.`);
S('c6.t2.title', `The Island of Hidden Groups`, `The Island of Hidden Groups`);
S('c6.cl.name', `Creature`, `المخلوق`); S('c6.cl.wing', `Wing span`, `Wing span`); S('c6.cl.body', `Body size`, `Body size`); S('c6.cl.glow', `Glow`, `Glow`);
Q('c6.t21', [`None of these creatures has a species label. Which kind of learning finds groups in unlabeled data?`, `لا يوجد Label للنوع على أي من هذه المخلوقات. أي نوع من التعلم يجد المجموعات في بيانات بلا Labels؟`],
  [`Unsupervised learning (clustering)`, `Unsupervised learning (Clustering)`], [`Supervised classification`, `Supervised classification`], [`Regression`, `Regression`],
  [`Is there a column of right answers?`, `هل هناك عمود للإجابات الصحيحة؟`], [`No labels means no supervision.`, `بلا Labels لا إشراف.`],
  [`Without labels, we use unsupervised learning. Clustering groups similar examples.`, `بلا Labels نستخدم Unsupervised learning. الـ Clustering يجمع الأمثلة المتشابهة.`]);
Q('c6.t22', [`Which two creatures look most alike in the table?`, `أي مخلوقين يبدوان أكثر تشابهًا في الجدول؟`],
  [`Cloudlet and Mistling`, `Cloudlet و Mistling`], [`Cloudlet and Windrake`, `Cloudlet و Windrake`], [`Skyfin and Emberfox`, `Skyfin و Emberfox`],
  [`Compare their three numbers.`, `قارن أرقامهما الثلاثة.`], [`Close numbers mean close creatures.`, `الأرقام المتقاربة تعني مخلوقات متقاربة.`],
  [`Cloudlet (2, 2, 1) and Mistling (3, 2, 2) have nearly the same values, so they would be put in the same cluster.`, `Cloudlet (2, 2, 1) و Mistling (3, 2, 2) قيمهما شبه متطابقة، فسيُوضعان في Cluster واحد.`]);
S('c6.k.label', `K (clusters):`, `K (clusters):`); S('c6.k.n', `Group {n}`, `Group {n}`); S('c6.k.note', `A simplified example: the groups for each K are precomputed.`, `مثال مبسّط: مجموعات كل K محسوبة مسبقًا.`);
H('c6.t23', [`Choose K, the number of clusters, so that the creatures fall into their three natural groups.`, `اختر K، عدد الـ Clusters، بحيث تقع المخلوقات في مجموعاتها الثلاث الطبيعية.`],
  [`Look at the table: how many sets of similar creatures can you see?`, `انظر إلى الجدول: كم مجموعة من المخلوقات المتشابهة تراها؟`], [`Two small, two with large wings, two glowing.`, `اثنان صغيران، واثنان بأجنحة كبيرة، واثنان متوهجان.`],
  [`K = 3 matches the three groups. K = 1 puts everyone together; K = 5 splits groups that belong together.`, `K = 3 يطابق المجموعات الثلاث. K = 1 يجمع الكل معًا؛ وK = 5 يفرّق مجموعات متقاربة.`]);
Q('c6.t24', [`In K-Means, what does K stand for?`, `في K-Means، إلى ماذا يشير K؟`],
  [`The number of clusters we ask the algorithm to find`, `عدد الـ Clusters الذي نطلب من الخوارزمية إيجاده`], [`The number of creatures`, `عدد المخلوقات`], [`The number of features`, `عدد الـ Features`],
  [`You choose K before the algorithm runs.`, `تختار K قبل تشغيل الخوارزمية.`], [`It counts groups, not creatures.`, `يعدّ المجموعات لا المخلوقات.`],
  [`K is the number of clusters you ask for. Elbow and Silhouette checks help choose it.`, `K هو عدد الـ Clusters الذي تطلبه. ويساعد فحص Elbow وSilhouette على اختياره.`]);
Q('c6.t25', [`The algorithm found three clusters. Does that prove there are three real species?`, `وجدت الخوارزمية ثلاثة Clusters. هل يثبت ذلك وجود ثلاثة أنواع حقيقية؟`],
  [`No. Clusters are patterns in the data; experts must check what they mean`, `لا. الـ Clusters أنماط في البيانات، وعلى الخبراء فحص معناها`], [`Yes, clusters are always real species`, `نعم، الـ Clusters دائمًا أنواع حقيقية`], [`Yes, if K was 3`, `نعم، إذا كان K يساوي 3`],
  [`Did anyone ever label these creatures?`, `هل وسم أحدٌ هذه المخلوقات يومًا؟`], [`A pattern is a clue, not a proof.`, `النمط دليل لا برهان.`],
  [`Clusters show similarity in the measurements. Whether they match real categories needs outside evidence.`, `تُظهر الـ Clusters تشابهًا في القياسات. أما هل تطابق فئات حقيقية فيحتاج دليلًا من خارجها.`]);

/* scene 3 */
S('c6.s3.1', `Two paths. Two ways to learn. Which will you walk?`, `طريقان. وطريقتان للتعلم. أيهما ستسلكان؟`);
S('c6.s3.2', `I learn from examples that come with answers. That is **supervised learning**. Cat photos labeled "cat", house sales with known prices.`, `أتعلم من أمثلة معها إجابات. هذا هو **Supervised learning**. صور قطط موسومة "قطة"، ومبيعات منازل بأسعار معروفة.`);
S('c6.s3.3', `I learn from examples with no answers. That is **unsupervised learning**. I look for groups and shapes that were not given to me.`, `أتعلم من أمثلة بلا إجابات. هذا هو **Unsupervised learning**. أبحث عن مجموعات وأشكال لم تُعطَ لي.`);
S('c6.s3.4', `A bridge is broken between our two paths. Show us which path fits each problem and we can mend it.`, `جسر مكسور بين طريقينا. أرينا أي طريق يناسب كل مشكلة ونستطيع إصلاحه.`);
S('c6.s3.win', `The bridge is whole. Neither path is better. They answer different questions.`, `عاد الجسر سليمًا. لا طريق أفضل من الآخر. هما يجيبان عن أسئلة مختلفة.`);
S('c6.s3.win2', `One more lesson from the Silent Oracle: when a clustering run gives you Group 2, the machine does not tell you what Group 2 means. People name it. Not every cluster is a real category.`, `درس آخر من Silent Oracle: عندما يعطيك الـ Clustering المجموعة 2، لا تقول الآلة ما معناها. الناس هم من يسمّونها. وليس كل Cluster فئة حقيقية.`);
S('c6.s3.t1', `The Convergence Gate lies northeast of the dock. The Keeper is waiting there.`, `Convergence Gate في شمال شرق الرصيف. والـ Keeper ينتظر هناك.`);
S('c6.t3.title', `The Twin Paths of Learning`, `The Twin Paths of Learning`);
